function u(v, n) { v = v == null ? "" : String(v).trim(); return v ? esc(v) : "<span class=bl>" + "_".repeat(n || 18) + "</span>"; }
function md(src, d) { // мини-разметка: # заголовок, ^ подзаголовок, ## раздел, - пункт, <> лево||право, >> вправо
  return src.split("\n").map(function (l) {
    l = l.replace(/\{\{(\w+)(?:\|(\d+))?\}\}/g, function (_, k, n) { return u(d[k], +n || 18); }).replace(/\*\*(.+?)\*\*/g, "<b>$1</b>");
    if (/^# /.test(l)) return "<h1>" + l.slice(2) + "</h1>";
    if (/^\^ /.test(l)) return "<h3>" + l.slice(2) + "</h3>";
    if (/^## /.test(l)) return "<h2>" + l.slice(3) + "</h2>";
    if (/^- /.test(l)) return "<p class=li>– " + l.slice(2) + "</p>";
    if (/^<> /.test(l)) { var a = l.slice(3).split("||"); return "<p class=lr><span>" + a[0] + "</span><span>" + (a[1] || "") + "</span></p>"; }
    if (/^>> /.test(l)) return "<p class=r>" + l.slice(3) + "</p>";
    if (!l.trim()) return "<p>&nbsp;</p>";
    return "<p>" + l + "</p>";
  }).join("");
}
